from work import *
id='local002'
init(id,'每日玩具销售件数（order_items行）','daily sales data', '''# 独立题解（揭示前）
题目：“Can you calculate the 5-day symmetric moving average of predicted toy sales for December 5 to 8, 2018, using daily sales data from January 1, 2017, to August 29, 2018, with a simple linear regression model? Finally provide the sum of those four 5-day moving averages?”
没有业务文档。将sales理解为售出玩具件数，每order_items一行为一件；订单purchase时间为销售日期，类别翻译为toys。不额外过滤状态。sales也可指金额，属未证实假设，实验计算两种。
训练日历从2017-01-01到2018-08-29包含首尾，无销售日补零。x为相对起点日数，y为日玩具件数。OLS b=(sum(x*y)-sum(x)*sum(y)/n)/(sum(x*x)-sum(x)^2/n)，a=avg(y)-b*avg(x)。预测2018-12-03至10；各中心日12月5至8的对称窗口为前后2日含中心5天。线性预测的对称平均数学上等于中心预测，仍显式平均验证。输出四个平均的总和。不截负预测、不四舍五入中间值。另验证有销售日序与真实日序的差异。
''')
base='''WITH RECURSIVE calendar(d) AS (SELECT date('2017-01-01') UNION ALL SELECT date(d,'+1 day') FROM calendar WHERE d<'2018-08-29'), daily AS (SELECT date(o.order_purchase_timestamp) d, COUNT(*) units,SUM(i.price) revenue FROM orders o JOIN order_items i ON o.order_id=i.order_id JOIN products p ON i.product_id=p.product_id JOIN product_category_name_translation t ON p.product_category_name=t.product_category_name WHERE t.product_category_name_english='toys' AND date(o.order_purchase_timestamp) BETWEEN '2017-01-01' AND '2018-08-29' GROUP BY 1), train AS (SELECT c.d,julianday(c.d)-julianday('2017-01-01') x,coalesce(units,0) y,coalesce(revenue,0) revenue FROM calendar c LEFT JOIN daily USING(d)), stats AS (SELECT count(*) n,sum(x) sx,sum(y) sy,sum(x*x) sxx,sum(x*y) sxy,avg(x) mx,avg(y) my FROM train), model AS (SELECT (sxy-sx*sy/n)/(sxx-sx*sx/n) b,my-(sxy-sx*sy/n)/(sxx-sx*sx/n)*mx a FROM stats), forecast(d) AS (SELECT date('2018-12-03') UNION ALL SELECT date(d,'+1 day') FROM forecast WHERE d<'2018-12-10'), predictions AS (SELECT d,a+b*(julianday(d)-julianday('2017-01-01')) yhat FROM forecast CROSS JOIN model), smooth AS (SELECT c.d,avg(p.yhat) ma FROM predictions c JOIN predictions p ON p.d BETWEEN date(c.d,'-2 day') AND date(c.d,'+2 day') WHERE c.d BETWEEN '2018-12-05' AND '2018-12-08' GROUP BY c.d) '''
query(id,base+'SELECT n,sx,sy,sxx,sxy,a,b,(SELECT count(*) FROM daily) nonzero_days,(SELECT sum(revenue) FROM daily) revenue FROM stats CROSS JOIN model','stats.json')
query(id,base+'SELECT s.*,p.yhat,s.ma-p.yhat identity_error FROM smooth s JOIN predictions p USING(d)','smooth.json')
query(id,base.replace('coalesce(units,0) y','coalesce(revenue,0) y')+'SELECT sum(ma) revenue_answer FROM smooth','revenue-alternative.json')
query(id,base.replace('FROM calendar c LEFT JOIN daily USING(d)','FROM calendar c JOIN daily USING(d)')+'SELECT n,a,b,(SELECT sum(ma) FROM smooth) sparse_calendar_answer FROM stats CROSS JOIN model','missing-alternative.json')
fields={'population.eligibility':{'value':'Every calendar day, missing toy sales zero; item rows count as sold units irrespective of order status','basis':'assumed','rationale':'Daily sales implies regular calendar series; no status specified'},'population.conditions':{'value':["category English toys"],'basis':'request','quote':'toy sales'},'population.time':{'value':'Training 2017-01-01..2018-08-29 inclusive; forecast 2018-12-03..10; centers 2018-12-05..08','basis':'request','quote':'December 5 to 8, 2018'},'measure.formula':{'value':{'op':'custom','description':'Count item rows by calendar day including zero days; OLS on elapsed calendar days; predict 8 days; symmetric five-day arithmetic mean for each of four centers; sum four means'},'basis':'assumed','rationale':'sales taken as units; OLS and centered mean implemented explicitly'},'grouping':{'value':[],'basis':'request','quote':'sum of those four 5-day moving averages'},'selection':'n/a','output':{'value':{'rowMode':'scalar','columns':['sum_moving_averages']},'basis':'request','quote':'sum of those four 5-day moving averages'}}
finish(id,fields,base+'SELECT sum(ma) sum_moving_averages FROM smooth',{'algorithm':'Calendar-day OLS on toy item counts, zero filled, symmetric +/-2 day mean, sum 4','assumptions':['sales=units not revenue','all purchase statuses','zero-fill days']})
progress(id,'frozen');reveal(id)
